import create from 'zustand';

export type PomodoroState = {
  sessionLength: number; // in minutes
  breakLength: number; // in minutes
  longBreakLength: number; // in minutes
  timeLeft: number; // in seconds
  isRunning: boolean;
  isSession: boolean;
  cycleCount: number;
  start: () => void;
  pause: () => void;
  reset: () => void;
  setDurations: (session: number, breakL: number, longBreak: number) => void;
  toggleSession: () => void;
};

export const useStore = create<PomodoroState>((set, get) => {
  const defaults = {
    sessionLength: 25,
    breakLength: 5,
    longBreakLength: 15,
  };
  const load = (): PomodoroState => {
    const saved = localStorage.getItem('pomodoro-settings');
    if (saved) {
      const s = JSON.parse(saved);
      return {
        ...defaults,
        sessionLength: s.sessionLength ?? defaults.sessionLength,
        breakLength: s.breakLength ?? defaults.breakLength,
        longBreakLength: s.longBreakLength ?? defaults.longBreakLength,
        timeLeft: s.timeLeft ?? defaults.sessionLength * 60,
        isRunning: s.isRunning ?? false,
        isSession: s.isSession ?? true,
        cycleCount: s.cycleCount ?? 0,
      };
    }
    return {
      ...defaults,
      timeLeft: defaults.sessionLength * 60,
      isRunning: false,
      isSession: true,
      cycleCount: 0,
    };
  };

  const base = load();

  const save = (state: PomodoroState) => {
    const { sessionLength, breakLength, longBreakLength, timeLeft, isRunning, isSession, cycleCount } = state;
    localStorage.setItem(
      'pomodoro-settings',
      JSON.stringify({ sessionLength, breakLength, longBreakLength, timeLeft, isRunning, isSession, cycleCount })
    );
  };

  return {
    ...base,
    start: () => set((state) => ({ ...state, isRunning: true })),
    pause: () => set((state) => ({ ...state, isRunning: false })),
    reset: () => {
      const sessionSec = get().sessionLength * 60;
      set({ ...base, timeLeft: sessionSec, cycleCount: 0, isRunning: false, isSession: true });
      save({ ...base, timeLeft: sessionSec, cycleCount: 0, isRunning: false, isSession: true });
    },
    setDurations: (s, b, l) => {
      set({ sessionLength: s, breakLength: b, longBreakLength: l, timeLeft: s * 60, isSession: true, cycleCount: 0 });
      save({ sessionLength: s, breakLength: b, longBreakLength: l, timeLeft: s * 60, isRunning: false, isSession: true, cycleCount: 0 });
    },
    toggleSession: () => {
      set((state) => {
        const nextIsSession = !state.isSession;
        const nextTime = nextIsSession ? state.sessionLength * 60 : state.breakLength * 60;
        return { ...state, isSession: nextIsSession, timeLeft: nextTime };
      });
      save({ ...get(), isSession: !get().isSession, timeLeft: !get().isSession ? get().sessionLength * 60 : get().breakLength * 60 });
    },
  };
});

